mkdir -p /app/bin /app/out; cat > /app/bin/fees.py <<'EOF'
import sys, os, csv, json, re, configparser, io
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal


def cents(s):
    return int((Decimal(str(s).strip().replace('$', '')) * 100).to_integral_value())


def pdigits(s):
    d = re.sub(r'\D', '', str(s))
    return int(d) if d else 0


def pdate(s):
    return datetime.strptime(s.strip(), '%Y-%m-%d').date()


def read_csv(path):
    with open(path, encoding='utf-8-sig', newline='') as f:
        return [{(k or '').strip(): (v or '').strip() for k, v in r.items()} for r in csv.DictReader(f)]


def parse_off(s):
    m = re.match(r'^([+-])(\d\d):?(\d\d)$', s.strip())
    sec = (int(m.group(2)) * 60 + int(m.group(3))) * 60
    return timedelta(seconds=-sec if m.group(1) == '-' else sec)


def parse_instant(s):
    s = s.strip()
    m = re.match(r'^(\d{4}-\d\d-\d\d)[T ](\d\d):(\d\d)(?::(\d\d))?(?:\.\d+)?\s*(Z|[+-]\d\d:?\d\d)?$', s)
    d = datetime.strptime(m.group(1), '%Y-%m-%d') + timedelta(hours=int(m.group(2)), minutes=int(m.group(3)), seconds=int(m.group(4) or 0))
    z = m.group(5)
    if z and z != 'Z':
        d -= parse_off(z)
    return d  # naive UTC


def main(inp, outp):
    ini = configparser.ConfigParser(interpolation=None)
    ini.optionxform = str
    with open(os.path.join(inp, 'policy.ini'), encoding='utf-8-sig') as f:
        ini.read_file(f)
    library = ini.get('statement', 'library')
    pstart = pdate(ini.get('statement', 'period_start'))
    pend = pdate(ini.get('statement', 'period_end'))
    base_off = parse_off(ini.get('clock', 'offset'))
    changes = []
    for part in ini.get('clock', 'changes', fallback='').split(';'):
        part = part.strip()
        if part:
            t, o = part.split()
            changes.append((parse_instant(t), parse_off(o)))
    changes.sort()
    items = {}
    cats = {}
    for sec in ini.sections():
        if sec.lower().startswith('item:'):
            g = ini[sec]
            items[sec[5:].strip().lower()] = dict(
                loan_days=int(g['loan_days']), renewals=int(g['renewals']), grace=int(g['grace_days']),
                daily=cents(g['daily']), cap=cents(g['loan_cap']))
        elif sec.lower().startswith('category:'):
            g = ini[sec]
            sc = g.get('statement_cap', 'none').strip()
            cats[sec[9:].strip().lower()] = dict(
                cap=None if sc.lower() == 'none' else cents(sc),
                discount=int(g.get('discount', '0').strip() or 0),
                exempt={x.strip().lower() for x in g.get('exempt', '').split(',') if x.strip()})

    branches = read_csv(os.path.join(inp, 'branches.csv'))
    bid = {}
    open_days = {}
    for b in branches:
        k = b['branch'].upper()
        bid[k] = b['branch']
        open_days[k] = {x.lower()[:3] for x in b['open_days'].split()}
    brow = {}
    star = {}
    for r in read_csv(os.path.join(inp, 'calendar.csv')):
        ds = r['date']
        if '..' in ds:
            a, b = ds.split('..')
            a, b = pdate(a), pdate(b)
        else:
            a = b = pdate(ds)
        st = r['status'].lower() == 'open'
        tgt = star if r['branch'] == '*' else brow.setdefault(r['branch'].upper(), {})
        d = a
        while d <= b:
            tgt[d] = st
            d += timedelta(days=1)
    wd = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun']

    def is_open(br, d):
        if d in brow.get(br, {}):
            return brow[br][d]
        if d in star:
            return star[d]
        return wd[d.weekday()] in open_days.get(br, set())

    def next_open(br, d):
        for _ in range(4000):
            if is_open(br, d):
                return d
            d += timedelta(days=1)
        return d

    patrows = {}
    pname = {}
    for r in read_csv(os.path.join(inp, 'patrons.csv')):
        n = pdigits(r['patron'])
        patrows.setdefault(n, []).append((pdate(r['since']), r['category'].lower()))
        pname[n] = r['patron']
    for v in patrows.values():
        v.sort()

    def cat_on(n, d):
        c = None
        for s, cat in patrows.get(n, []):
            if s <= d:
                c = cat
        if c is None and patrows.get(n):
            c = patrows[n][0][1]
        return c

    waivers = []
    for r in read_csv(os.path.join(inp, 'waivers.csv')):
        if r['status'].lower() != 'active':
            continue
        v = r['value'].strip()
        waivers.append((pdigits(r['patron']), r['loan'], None if v.lower() == 'full' else cents(v)))

    def local(dt):
        off = base_off
        for t, o in changes:
            if dt >= t:
                off = o
        return dt + off

    # events
    events = {}
    exdir = os.path.join(inp, 'exports')
    for fn in sorted(os.listdir(exdir)):
        p = os.path.join(exdir, fn)
        low = fn.lower()
        if not (low.endswith('.csv') or low.endswith('.jsonl')) or not os.path.isfile(p):
            continue
        recs = []
        if low.endswith('.csv'):
            recs = read_csv(p)
            for r in recs:
                r['_t'] = datetime.strptime(r['time'], '%Y-%m-%d %H:%M') if r.get('time') else None
        else:
            with open(p, encoding='utf-8-sig') as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    r = {k: ('' if v is None else str(v).strip()) for k, v in json.loads(line).items()}
                    r['_t'] = local(parse_instant(r['at'])) if r.get('at') else None
                    recs.append(r)
        for r in recs:
            eid = r.get('event', '')
            if eid and eid not in events:
                r['type'] = r.get('type', '').lower()
                events[eid] = r
    cancelled = {r['target'] for r in events.values() if r['type'] == 'void'}
    live = [r for e, r in events.items() if r['type'] != 'void' and e not in cancelled]

    loans = {}
    for r in live:
        if r['type'] == 'checkout':
            d = r['_t'].date()
            if d > pend:
                continue
            loans[r['loan']] = dict(id=r['loan'], patron=pdigits(r['patron']), item=r.get('item', ''),
                                    itype=r['item_type'].lower(), branch=r['branch'].upper(), co=d, ev=[])
    for r in live:
        if r['type'] in ('renew', 'return') and r.get('loan') in loans:
            loans[r['loan']]['ev'].append(r)

    rows = []
    for L in loans.values():
        it = items[L['itype']]
        br = L['branch']
        due = next_open(br, L['co'] + timedelta(days=it['loan_days']))
        nren = 0
        ret = None
        for r in sorted(L['ev'], key=lambda r: r['_t']):
            d = r['_t'].date()
            if r['type'] == 'return':
                ret = d - timedelta(days=1) if r.get('via', '').lower() == 'dropbox' else d
                break
            if d <= due and nren < it['renewals'] and d <= pend:
                nren += 1
                due = next_open(br, d + timedelta(days=it['loan_days']))
        if ret is not None and ret > pend:
            ret = None
        if ret is not None and ret < pstart:
            continue
        end = ret if ret is not None else pend
        od = 0
        d = due + timedelta(days=1)
        while d <= end:
            if is_open(br, d):
                od += 1
            d += timedelta(days=1)
        if od == 0:
            continue
        charged = od if od > it['grace'] else 0
        fee = charged * it['daily']
        c = cats[cat_on(L['patron'], L['co'])]
        if L['itype'] in c['exempt']:
            fee = 0
        fee = min(fee, it['cap'])
        fee = (fee * (100 - c['discount']) + 50) // 100
        L.update(due=due, ret=ret, od=od, charged=charged, assessed=fee)
        rows.append(L)

    stm = {}
    for L in rows:
        stm.setdefault(L['patron'], []).append(L)
    out_st = []
    for n in sorted(stm):
        ls = stm[n]
        for L in ls:
            w = 0
            full = False
            for wp, wl, wv in waivers:
                if wp == n and (wl == '*' or wl == L['id']):
                    if wv is None:
                        full = True
                    else:
                        w += wv
            L['waived'] = L['assessed'] if full else min(w, L['assessed'])
            L['net'] = L['assessed'] - L['waived']
            L['capped'] = 0
        cat = cat_on(n, pend)
        cap = cats[cat]['cap']
        if cap is not None:
            excess = sum(L['net'] for L in ls) - cap
            for L in sorted(ls, key=lambda L: (L['due'], L['id']), reverse=True):
                if excess <= 0:
                    break
                g = min(excess, L['net'])
                L['capped'] = g
                excess -= g
        ls.sort(key=lambda L: (L['due'], L['id']))
        lo = []
        for L in ls:
            L['billed'] = L['net'] - L['capped']
            lo.append({"loan": L['id'], "item": L['item'], "item_type": L['itype'] if False else next(
                (s[5:].strip() for s in ini.sections() if s.lower() == 'item:' + L['itype']), L['itype']),
                "branch": bid.get(L['branch'], L['branch']),
                "checkout": L['co'].isoformat(), "due": L['due'].isoformat(),
                "returned": L['ret'].isoformat() if L['ret'] else None,
                "overdue_days": L['od'], "charged_days": L['charged'], "assessed": L['assessed'],
                "waived": L['waived'], "capped": L['capped'], "billed": L['billed']})
        s = {"patron": pname.get(n, str(n)),
             "category": next((x[9:].strip() for x in ini.sections() if x.lower() == 'category:' + cat), cat),
             "loans": lo}
        for k in ('assessed', 'waived', 'capped', 'billed'):
            s[k] = sum(x[k] for x in lo)
        out_st.append(s)
    summ = []
    for b in branches:
        k = b['branch'].upper()
        ls = [L for L in rows if L['branch'] == k]
        e = {"branch": b['branch'], "loans": len(ls), "charged_days": sum(L['charged'] for L in ls)}
        for key in ('assessed', 'waived', 'capped', 'billed'):
            e[key] = sum(L[key] for L in ls)
        summ.append(e)
    res = {"library": library, "period": {"start": pstart.isoformat(), "end": pend.isoformat()},
           "statements": out_st, "branches": summ}
    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(res, f, indent=2)
        f.write('\n')


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
